int matrixChainOrder(vector<int>& p) {
    int n = p.size() - 1;                        // number of matrices
    vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));
    for (int len = 2; len <= n; len++)
        for (int i = 1; i + len - 1 <= n; i++) {
            int j = i + len - 1;
            dp[i][j] = INT_MAX;
            for (int k = i; k < j; k++)
                dp[i][j] = min(dp[i][j],
                               dp[i][k] + dp[k + 1][j] + p[i - 1] * p[k] * p[j]);
        }
    return dp[1][n];
}

